"""Provider factory — selects the right LLMProvider at runtime."""

from __future__ import annotations

import os
from typing import Any

from worthapply.providers.base import LLMProvider


def get_provider(**kwargs: Any) -> LLMProvider:
    """Return an LLMProvider based on the LLM_PROVIDER env var.

    Raises clear errors for misconfiguration rather than silently falling back.
    """
    provider_name = os.getenv("LLM_PROVIDER", "xai").lower().strip()

    if provider_name == "xai":
        from worthapply.providers.xai_provider import XAIProvider

        return XAIProvider(**kwargs)

    if provider_name == "local":
        from worthapply.providers.local_provider import LocalProvider

        return LocalProvider(**kwargs)

    raise ValueError(
        f"Unknown LLM_PROVIDER='{provider_name}'. "
        "Supported values: 'xai' (cloud, default), 'local' (development)."
    )

"""Tests for the evaluation scoring module."""

from baseline.evaluator import score_priority, score_recommendation, score_fit, score_risk


class TestScorePriority:
    def test_exact_match(self):
        assert score_priority("HIGH", "HIGH") == 1.0
        assert score_priority("MEDIUM", "MEDIUM") == 1.0
        assert score_priority("LOW", "LOW") == 1.0

    def test_adjacent(self):
        assert score_priority("HIGH", "MEDIUM") == 0.5
        assert score_priority("MEDIUM", "LOW") == 0.5

    def test_opposite(self):
        assert score_priority("HIGH", "LOW") == 0.0
        assert score_priority("LOW", "HIGH") == 0.0

    def test_empty(self):
        assert score_priority("", "HIGH") == 0.0
        assert score_priority("HIGH", "") == 0.0

    def test_case_insensitive(self):
        assert score_priority("high", "HIGH") == 1.0
        assert score_priority("  HIGH  ", "HIGH") == 1.0


class TestScoreRecommendation:
    def test_exact(self):
        assert score_recommendation("APPLY", "APPLY") == 1.0

    def test_adjacent(self):
        assert score_recommendation("APPLY", "APPLY_IF_TIME") == 0.5

    def test_opposite(self):
        assert score_recommendation("APPLY", "LOW_PRIORITY") == 0.0


class TestScoreFit:
    def test_within_range(self):
        assert score_fit(75.0, [70.0, 80.0]) == 1.0

    def test_at_boundary(self):
        assert score_fit(70.0, [70.0, 80.0]) == 1.0
        assert score_fit(80.0, [70.0, 80.0]) == 1.0

    def test_within_extended_range(self):
        assert score_fit(60.0, [70.0, 80.0]) == 0.5
        assert score_fit(90.0, [70.0, 80.0]) == 0.5

    def test_outside_all_ranges(self):
        assert score_fit(10.0, [70.0, 80.0]) == 0.0

    def test_invalid_range(self):
        assert score_fit(50.0, []) == 0.0


class TestScoreRisk:
    def test_exact(self):
        assert score_risk("LOW", "LOW") == 1.0

    def test_adjacent(self):
        assert score_risk("LOW", "MEDIUM") == 0.5

    def test_opposite(self):
        assert score_risk("LOW", "HIGH") == 0.0

"""Run evaluation across baseline and iteration results.

Usage:
    python -m evaluation.evaluate baseline
    python -m evaluation.evaluate final
    python -m evaluation.evaluate --all
"""

from __future__ import annotations

import argparse
import json
import sys
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))

RESULTS_DIR = PROJECT_ROOT / "results"


def load_results(version: str) -> list[dict] | None:
    path = RESULTS_DIR / version / "raw_results.json"
    if not path.exists():
        print(f"No results found at {path}")
        return None
    with open(path, encoding="utf-8") as f:
        return json.load(f)


def compare_versions(versions: list[str]) -> str:
    """Generate a comparison table across versions."""
    lines = ["# Cross-Version Comparison", ""]
    headers = ["Metric"] + versions
    rows = []

    data = {}
    for v in versions:
        eval_path = RESULTS_DIR / v / "evaluation.json"
        if eval_path.exists():
            with open(eval_path, encoding="utf-8") as f:
                data[v] = json.load(f)
        else:
            data[v] = None

    metrics = [
        ("Exact Accuracy", lambda d: d.get("primary_metric", {}).get("exact_accuracy", "N/A")),
        ("Weighted Accuracy", lambda d: d.get("primary_metric", {}).get("weighted_accuracy", "N/A")),
        ("Recommendation Acc.", lambda d: d.get("secondary_metrics", {}).get("recommendation_accuracy", "N/A")),
        ("Fit Accuracy", lambda d: d.get("secondary_metrics", {}).get("fit_accuracy", "N/A")),
        ("Risk Accuracy", lambda d: d.get("secondary_metrics", {}).get("risk_accuracy", "N/A")),
    ]

    for name, extractor in metrics:
        row = [name]
        for v in versions:
            if data.get(v):
                val = extractor(data[v])
                row.append(f"{val}" if isinstance(val, str) else f"{val:.4f}")
            else:
                row.append("N/A")
        rows.append(row)

    lines.append("| " + " | ".join(headers) + " |")
    lines.append("| " + " | ".join(["---"] * len(headers)) + " |")
    for row in rows:
        lines.append("| " + " | ".join(row) + " |")
    lines.append("")

    return "\n".join(lines)


def main():
    parser = argparse.ArgumentParser(description="WorthApply evaluation")
    parser.add_argument("version", nargs="?", default="baseline", help="Version to evaluate (baseline, final, etc.)")
    parser.add_argument("--all", action="store_true", help="Compare all available versions")
    args = parser.parse_args()

    if args.all:
        versions = []
        for d in sorted(RESULTS_DIR.iterdir()):
            if d.is_dir() and (d / "evaluation.json").exists():
                versions.append(d.name)
        if versions:
            report = compare_versions(versions)
            print(report)
            out = RESULTS_DIR / "comparison.md"
            out.write_text(report, encoding="utf-8")
            print(f"\nSaved to {out}")
        else:
            print("No evaluated versions found. Run baseline first.")
    else:
        # Import and run the appropriate evaluator
        if args.version == "baseline":
            from baseline.evaluator import main as eval_main
            eval_main()
        else:
            print(f"Evaluator for '{args.version}' not yet implemented.")


if __name__ == "__main__":
    main()

"""Resume parser — extracts text from PDF and DOCX files."""

from __future__ import annotations

import io
import logging
from pathlib import Path
from typing import BinaryIO

logger = logging.getLogger(__name__)


def parse_pdf(source: str | Path | BinaryIO) -> str:
    """Extract text from a PDF file or file-like object."""
    from PyPDF2 import PdfReader

    try:
        if isinstance(source, (str, Path)):
            reader = PdfReader(str(source))
        else:
            reader = PdfReader(source)

        pages = []
        for page in reader.pages:
            text = page.extract_text()
            if text:
                pages.append(text.strip())
        return "\n\n".join(pages)
    except Exception as exc:
        logger.error("PDF parse error: %s", exc)
        return ""


def parse_docx(source: str | Path | BinaryIO) -> str:
    """Extract text from a DOCX file or file-like object."""
    from docx import Document

    try:
        if isinstance(source, (str, Path)):
            doc = Document(str(source))
        else:
            doc = Document(source)

        paragraphs = []
        for para in doc.paragraphs:
            text = para.text.strip()
            if text:
                paragraphs.append(text)
        return "\n\n".join(paragraphs)
    except Exception as exc:
        logger.error("DOCX parse error: %s", exc)
        return ""


def parse_resume(source: str | Path | BinaryIO, filename: str = "") -> str:
    """Parse a resume file, auto-detecting format from extension or filename.

    Args:
        source: File path or file-like object.
        filename: Original filename (used for format detection when source is a stream).

    Returns:
        Extracted text, or empty string on failure.
    """
    if isinstance(source, (str, Path)):
        ext = Path(source).suffix.lower()
    else:
        ext = Path(filename).suffix.lower() if filename else ""

    if ext == ".pdf":
        return parse_pdf(source)
    elif ext in (".docx", ".doc"):
        return parse_docx(source)
    elif ext in (".txt", ".md"):
        if isinstance(source, (str, Path)):
            return Path(source).read_text(encoding="utf-8")
        else:
            raw = source.read()
            return raw.decode("utf-8") if isinstance(raw, bytes) else raw
    else:
        logger.warning("Unsupported resume format: %s", ext or "(unknown)")
        return ""

"""Web search tool — searches the web for verification information.

Uses the Serper API (https://serper.dev) when SERPER_API_KEY is set.
Falls back to a no-op result when no search API is configured.
"""

from __future__ import annotations

import logging
import os
import time
from dataclasses import dataclass, field

import httpx

logger = logging.getLogger(__name__)

_TIMEOUT = 10.0


@dataclass
class SearchResult:
    title: str = ""
    url: str = ""
    snippet: str = ""


@dataclass
class SearchResponse:
    query: str = ""
    results: list[SearchResult] = field(default_factory=list)
    error: str | None = None
    elapsed_ms: float = 0.0

    @property
    def ok(self) -> bool:
        return self.error is None


async def web_search(query: str, num_results: int = 5) -> SearchResponse:
    """Search the web for the given query.

    Returns structured search results. If no search API is configured,
    returns an empty result set with a descriptive error.
    """
    api_key = os.getenv("SERPER_API_KEY")
    if not api_key:
        return SearchResponse(
            query=query,
            error="No search API configured (SERPER_API_KEY not set). Cannot independently verify.",
        )

    return await _serper_search(query, api_key, num_results)


async def _serper_search(
    query: str, api_key: str, num_results: int
) -> SearchResponse:
    start = time.perf_counter()
    try:
        async with httpx.AsyncClient(timeout=_TIMEOUT) as client:
            resp = await client.post(
                "https://google.serper.dev/search",
                json={"q": query, "num": num_results},
                headers={
                    "X-API-KEY": api_key,
                    "Content-Type": "application/json",
                },
            )
            elapsed = (time.perf_counter() - start) * 1000

            if resp.status_code != 200:
                return SearchResponse(
                    query=query,
                    error=f"Search API HTTP {resp.status_code}",
                    elapsed_ms=elapsed,
                )

            data = resp.json()
            results = []
            for item in data.get("organic", [])[:num_results]:
                results.append(SearchResult(
                    title=item.get("title", ""),
                    url=item.get("link", ""),
                    snippet=item.get("snippet", ""),
                ))

            return SearchResponse(
                query=query,
                results=results,
                elapsed_ms=round(elapsed, 1),
            )
    except Exception as exc:
        elapsed = (time.perf_counter() - start) * 1000
        return SearchResponse(
            query=query,
            error=f"Search failed: {exc}",
            elapsed_ms=elapsed,
        )

"""Opportunity Risk / Freshness Agent — identifies risk indicators."""

from __future__ import annotations

from worthapply.agents.base import BaseAgent
from worthapply.models.schemas import (
    CompanyVerification,
    JobProfile,
    RiskAssessment,
)
from worthapply.providers.base import LLMProvider

_SYSTEM = """You are an opportunity risk analyst. Your job is to identify
risk INDICATORS in job postings — NOT to accuse companies of fraud.

Rules:
- A risk indicator is a signal worth investigating, NOT proof of a problem.
- NEVER state "this is a scam" or "this company is fraudulent."
- Instead use language like: "Potential risk indicator detected"
- Possible signals: old posting, missing official listing, conflicting info,
  unusual requirements, suspicious destination, missing expected fields.
- Assign severity: LOW (minor concern), MEDIUM (worth investigating),
  HIGH (significant concern).
- Provide evidence for every signal.
- A company with limited web presence is NOT automatically suspicious.
- risk_level should be LOW if 0-1 low signals, MEDIUM if multiple signals
  or any medium signal, HIGH only for significant converging concerns."""

_PROMPT = """Analyze this opportunity for risk indicators.

## Job Details
Title: {title}
Company: {company}
Location: {location}
Type: {employment_type}
Posted: {posting_date}
Source: {source_url}
Application URL: {application_url}

## Job Description Summary
Required Skills: {required_skills}
Preferred Skills: {preferred_skills}
Experience: {experience_req}
Responsibilities count: {resp_count}

## Company Verification Summary
Verification Status: {verification_status}
Website Found: {website_found}
Careers Page Found: {careers_found}
Job Listing Found: {listing_found}
Verification Confidence: {verification_confidence}
Unresolved Questions: {unresolved}

Identify any risk indicators with evidence and severity."""


class OpportunityRiskAgent(BaseAgent):
    name = "opportunity_risk"

    def __init__(self, provider: LLMProvider) -> None:
        super().__init__(provider)

    async def run(
        self,
        job: JobProfile,
        company_verification: CompanyVerification | None = None,
    ) -> RiskAssessment:
        cv = company_verification or CompanyVerification()

        prompt = _PROMPT.format(
            title=job.title or "Not specified",
            company=job.company or "Not specified",
            location=job.location or "Not specified",
            employment_type=job.employment_type or "Not specified",
            posting_date=job.posting_date or "Not available",
            source_url=job.source_url or "Not provided",
            application_url=job.application_url or "Not provided",
            required_skills=", ".join(job.required_skills) or "None listed",
            preferred_skills=", ".join(job.preferred_skills) or "None listed",
            experience_req=job.experience_requirement or "Not specified",
            resp_count=len(job.responsibilities),
            verification_status=cv.verification_status.value,
            website_found=cv.website_found,
            careers_found=cv.careers_page_found,
            listing_found=cv.job_listing_found,
            verification_confidence=cv.confidence,
            unresolved="; ".join(cv.unresolved_questions) or "None",
        )

        resp = await self.generate_structured(
            prompt, RiskAssessment, system=_SYSTEM, max_tokens=2048
        )

        if resp.ok and resp.structured:
            return resp.structured

        return RiskAssessment(summary="Unable to assess risk due to LLM error.")

"""Pipeline state — tracks progress through the analysis workflow."""

from __future__ import annotations

import time
import uuid
from dataclasses import dataclass, field
from enum import Enum
from typing import Any

from worthapply.models.schemas import (
    CompanyVerification,
    JobProfile,
    OpportunityReport,
    RiskAssessment,
    StudentFitResult,
)
from worthapply.providers.base import LLMUsage


class StageStatus(str, Enum):
    PENDING = "PENDING"
    RUNNING = "RUNNING"
    COMPLETED = "COMPLETED"
    FAILED = "FAILED"
    SKIPPED = "SKIPPED"


@dataclass
class StageResult:
    status: StageStatus = StageStatus.PENDING
    started_at: float = 0.0
    finished_at: float = 0.0
    error: str | None = None
    usage: LLMUsage | None = None

    @property
    def elapsed_ms(self) -> float:
        if self.started_at and self.finished_at:
            return round((self.finished_at - self.started_at) * 1000, 1)
        return 0.0


@dataclass
class PipelineState:
    """Full state for one opportunity analysis run."""

    run_id: str = field(default_factory=lambda: str(uuid.uuid4())[:12])
    started_at: float = field(default_factory=time.perf_counter)

    # Inputs
    student_text: str = ""
    job_text: str = ""
    job_url: str = ""

    # Intermediate results
    job_profile: JobProfile | None = None
    student_fit: StudentFitResult | None = None
    company_verification: CompanyVerification | None = None
    risk_assessment: RiskAssessment | None = None
    evidence_quality: str = ""
    unsupported_claims: int = 0

    # Final output
    report: OpportunityReport | None = None

    # Stage tracking
    stages: dict[str, StageResult] = field(default_factory=lambda: {
        "job_intelligence": StageResult(),
        "student_fit": StageResult(),
        "company_verification": StageResult(),
        "opportunity_risk": StageResult(),
        "evidence_verification": StageResult(),
        "decision_synthesis": StageResult(),
    })

    # Usage tracking
    all_usage: list[LLMUsage] = field(default_factory=list)

    @property
    def total_elapsed_ms(self) -> float:
        return round((time.perf_counter() - self.started_at) * 1000, 1)

    @property
    def total_cost(self) -> float:
        return sum(u.estimated_cost_usd for u in self.all_usage)

    @property
    def total_tokens(self) -> int:
        return sum(u.total_tokens for u in self.all_usage)

    def begin_stage(self, name: str) -> None:
        if name in self.stages:
            self.stages[name].status = StageStatus.RUNNING
            self.stages[name].started_at = time.perf_counter()

    def complete_stage(self, name: str, usage: LLMUsage | None = None) -> None:
        if name in self.stages:
            self.stages[name].status = StageStatus.COMPLETED
            self.stages[name].finished_at = time.perf_counter()
            self.stages[name].usage = usage
            if usage:
                self.all_usage.append(usage)

    def fail_stage(self, name: str, error: str) -> None:
        if name in self.stages:
            self.stages[name].status = StageStatus.FAILED
            self.stages[name].finished_at = time.perf_counter()
            self.stages[name].error = error

    def get_progress(self) -> list[dict[str, Any]]:
        """Return stage progress for UI display."""
        return [
            {
                "stage": name,
                "status": result.status.value,
                "elapsed_ms": result.elapsed_ms,
            }
            for name, result in self.stages.items()
        ]

    def to_summary(self) -> dict[str, Any]:
        return {
            "run_id": self.run_id,
            "total_elapsed_ms": self.total_elapsed_ms,
            "total_cost_usd": round(self.total_cost, 6),
            "total_tokens": self.total_tokens,
            "stages": {
                name: {
                    "status": r.status.value,
                    "elapsed_ms": r.elapsed_ms,
                    "error": r.error,
                }
                for name, r in self.stages.items()
            },
        }

