"""Student Fit Agent — compares student evidence against job requirements."""

from __future__ import annotations

import re

from worthapply.agents.base import BaseAgent
from worthapply.models.schemas import (
    JobProfile,
    SkillMatch,
    SkillMatchLevel,
    StudentFitResult,
)
from worthapply.providers.base import LLMProvider

_SYSTEM = """You are an expert career counselor who evaluates student-job fit.

Rules:
- For EVERY skill, set match_level to MATCHED, PARTIALLY_MATCHED, or MISSING.
- For MATCHED / PARTIALLY_MATCHED you MUST cite specific evidence from the student profile.
- Do not list a skill as MISSING if the student profile clearly mentions it.
- fit_score: 0-30 weak, 30-60 partial, 60-80 good, 80-100 strong.
- Prefer the job's required/preferred skill lists — do not invent unrelated skills."""

_PROMPT = """Compare this student's profile against the job requirements.

## Student Profile
{student_text}

## Job Requirements
Title: {job_title}
Company: {company}
Required Skills: {required_skills}
Preferred Skills: {preferred_skills}
Experience Required: {experience_req}
Education Required: {education_req}
Responsibilities:
{responsibilities}

Return JSON with fit_score, required_skills and preferred_skills as arrays of objects:
{{"skill": "...", "match_level": "MATCHED|PARTIALLY_MATCHED|MISSING", "evidence": "..."}}
Use ONLY skills from the job lists above when possible."""


_ALIASES: dict[str, list[str]] = {
    "python": ["python", "django", "flask", "fastapi"],
    "fastapi": ["fastapi"],
    "aws": ["aws", "amazon web services", "s3", "ec2", "lambda"],
    "azure": ["azure", "microsoft azure", "azure ml", "databricks"],
    "tensorflow": ["tensorflow", "tf."],
    "pytorch": ["pytorch", "torch"],
    "machine learning": ["machine learning", "ml ", " ml", "sklearn", "scikit"],
    "deep learning": ["deep learning", "neural", "cnn", "rnn", "transformer"],
    "computer vision": ["computer vision", "opencv", "cv ", "image recognition"],
    "llm": ["llm", "large language", "genai", "generative ai", "gpt", "langchain"],
    "docker": ["docker", "container"],
    "kafka": ["kafka"],
    "redis": ["redis"],
    "sql": ["sql", "postgres", "mysql", "sqlite"],
    "rest": ["rest", "restful", "api"],
    "java": ["java"],
    "c++": ["c++", "cpp"],
}


class StudentFitAgent(BaseAgent):
    name = "student_fit"

    def __init__(self, provider: LLMProvider) -> None:
        super().__init__(provider)

    async def run(
        self, student_text: str, job: JobProfile
    ) -> StudentFitResult | None:
        prompt = _PROMPT.format(
            student_text=student_text[:4500],
            job_title=job.title,
            company=job.company,
            required_skills=", ".join(job.required_skills) or "Not specified",
            preferred_skills=", ".join(job.preferred_skills) or "Not specified",
            experience_req=job.experience_requirement or "Not specified",
            education_req=", ".join(job.education_requirements) or "Not specified",
            responsibilities="\n".join(f"- {r}" for r in job.responsibilities[:12])
            or "Not specified",
        )

        resp = await self.generate_structured(
            prompt, StudentFitResult, system=_SYSTEM, max_tokens=2048
        )

        if resp.ok and resp.structured:
            return self._ground(resp.structured, student_text, job)

        # LLM failed — still return deterministic grounding
        return self._ground(StudentFitResult(), student_text, job)

    def _ground(
        self, result: StudentFitResult, student_text: str, job: JobProfile
    ) -> StudentFitResult:
        """Reconcile LLM skill rows with resume text so MATCHED skills aren't shown as MISSING."""
        llm_by_skill = {
            self._norm(sm.skill): sm
            for sm in (result.required_skills + result.preferred_skills)
            if sm.skill
        }

        req_names = job.required_skills or [
            sm.skill for sm in result.required_skills if sm.skill
        ]
        pref_names = job.preferred_skills or [
            sm.skill for sm in result.preferred_skills if sm.skill
        ]

        # Prefer atomic skill tokens from job strings
        req_atoms = self._expand_skill_list(req_names)
        pref_atoms = self._expand_skill_list(pref_names)
        # Avoid duplicating preferred that already appear in required
        pref_atoms = [s for s in pref_atoms if self._norm(s) not in {self._norm(x) for x in req_atoms}]

        result.required_skills = [
            self._resolve_skill(name, llm_by_skill, student_text) for name in req_atoms
        ]
        result.preferred_skills = [
            self._resolve_skill(name, llm_by_skill, student_text) for name in pref_atoms
        ]

        # Recompute score if table contradicts a high score with all-MISSING
        matched = sum(
            1
            for sm in result.required_skills
            if sm.match_level == SkillMatchLevel.MATCHED
        )
        partial = sum(
            1
            for sm in result.required_skills
            if sm.match_level == SkillMatchLevel.PARTIALLY_MATCHED
        )
        total = max(len(result.required_skills), 1)
        grounded_score = round(100 * (matched + 0.5 * partial) / total, 1)

        all_missing = all(
            sm.match_level == SkillMatchLevel.MISSING for sm in result.required_skills
        ) and result.required_skills
        if all_missing and result.fit_score >= 60:
            # Force grounded score when LLM lied
            result.fit_score = grounded_score
        elif result.required_skills:
            # Blend: trust grounding more for local models
            result.fit_score = round(0.4 * result.fit_score + 0.6 * grounded_score, 1)

        return result

    def _resolve_skill(
        self,
        skill: str,
        llm_by_skill: dict[str, SkillMatch],
        student_text: str,
    ) -> SkillMatch:
        key = self._norm(skill)
        llm = llm_by_skill.get(key)
        evidence_hit, hit_level = self._resume_evidence(skill, student_text)

        if llm and llm.match_level != SkillMatchLevel.MISSING and llm.evidence.strip():
            # Keep LLM judgment if it provided real evidence
            return SkillMatch(
                skill=skill,
                match_level=llm.match_level,
                evidence=llm.evidence.strip(),
            )

        if evidence_hit:
            evidence = evidence_hit
            level = hit_level
            # If LLM said MATCHED but forgot evidence, still mark matched
            if llm and llm.match_level == SkillMatchLevel.MATCHED:
                level = SkillMatchLevel.MATCHED
            return SkillMatch(skill=skill, match_level=level, evidence=evidence)

        if llm and llm.match_level != SkillMatchLevel.MISSING:
            # LLM claimed match without evidence and resume has no hit → downgrade
            return SkillMatch(
                skill=skill,
                match_level=SkillMatchLevel.MISSING,
                evidence="",
            )

        return SkillMatch(skill=skill, match_level=SkillMatchLevel.MISSING, evidence="")

    def _resume_evidence(
        self, skill: str, student_text: str
    ) -> tuple[str, SkillMatchLevel]:
        text = student_text.lower()
        atoms = self._skill_atoms(skill)
        for atom in atoms:
            patterns = _ALIASES.get(atom, [atom])
            for pat in patterns:
                if pat.lower() in text:
                    # Grab a short supporting snippet
                    idx = text.find(pat.lower())
                    start = max(0, idx - 40)
                    end = min(len(student_text), idx + len(pat) + 60)
                    snippet = " ".join(student_text[start:end].split())
                    return f"Found in resume: …{snippet}…", SkillMatchLevel.MATCHED
        return "", SkillMatchLevel.MISSING

    def _expand_skill_list(self, skills: list[str]) -> list[str]:
        out: list[str] = []
        seen: set[str] = set()
        for raw in skills:
            parts = self._split_skill_phrase(raw)
            for p in parts:
                n = self._norm(p)
                if n and n not in seen:
                    seen.add(n)
                    out.append(p.strip())
        return out[:20]

    @staticmethod
    def _split_skill_phrase(raw: str) -> list[str]:
        """Turn 'Strong programming (Java, Python, C++)' into atomic skills."""
        raw = raw.strip()
        if not raw:
            return []
        inside = re.findall(r"\(([^)]+)\)", raw)
        if inside:
            bits = re.split(r"[,/;]| and ", inside[0])
            return [b.strip() for b in bits if b.strip()]
        # Comma-separated multi-skill lines
        if "," in raw and len(raw) < 80:
            return [b.strip() for b in raw.split(",") if b.strip()]
        return [raw]

    @staticmethod
    def _skill_atoms(skill: str) -> list[str]:
        base = skill.lower().strip()
        atoms = [base]
        # Also try last token: "Microsoft Azure" -> azure
        parts = re.split(r"[\s,/]+", base)
        if len(parts) > 1:
            atoms.append(parts[-1])
        return atoms

    @staticmethod
    def _norm(skill: str) -> str:
        return re.sub(r"\s+", " ", skill.strip().lower())

